const company = $('08 - Fetch Website').item.json;
const html = ($json.data || '') + '';
let status = 'OK';
if(!html || html.length < 200){ status = 'Error'; }

let clean = html
  .replace(/<script[\s\S]*?<\/script>/gi,' ')
  .replace(/<style[\s\S]*?<\/style>/gi,' ')
  .replace(/<svg[\s\S]*?<\/svg>/gi,' ')
  .replace(/<noscript[\s\S]*?<\/noscript>/gi,' ')
  .replace(/<!--[\s\S]*?-->/g,' ');

const titleMatch = clean.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
const pageTitle = titleMatch ? titleMatch[1].replace(/\s+/g,' ').trim() : '';

const metaMatch = clean.match(/<meta[^>]+name=["']description["'][^>]*content=["']([^"']*)["']/i);
const metaDescription = metaMatch ? metaMatch[1].trim() : '';

function collect(re){ 
  const res=[]; 
  let m; 
  while((m=re.exec(clean))!==null){ 
    const t=m[1].replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim(); 
    if(t) res.push(t); 
  } 
  return res; 
}

// Collects all headings without artificial limits
const h1 = collect(/<h1[^>]*>([\s\S]*?)<\/h1>/gi);
const h2 = collect(/<h2[^>]*>([\s\S]*?)<\/h2>/gi);
const h3 = collect(/<h3[^>]*>([\s\S]*?)<\/h3>/gi);

// Collects all links (removed the 15-link ceiling)
const links = [];
const lr = /<a[^>]+href=["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi;
let lm;
while((lm = lr.exec(clean)) !== null){
  const txt = lm[2].replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim();
  if(txt) links.push(txt + ' -> ' + lm[1]);
}

// Extracts full body text (removed the 4000 character limit)
let text = clean.replace(/<[^>]+>/g,' ').replace(/&nbsp;/g,' ').replace(/&amp;/g,'&').replace(/\s+/g,' ').trim();

const analysisId = (company.company || 'company').replace(/[^a-zA-Z0-9]+/g,'-').toLowerCase() + '-' + Date.now();

return { json: Object.assign({}, company, {
  websiteStatus: status,
  analysisId: analysisId,
  pageTitle: pageTitle,
  metaDescription: metaDescription,
  h1: h1, h2: h2, h3: h3,
  importantLinks: links,
  cleanedContent: text
}) };

