function normTitle(s){ return (s||'').toString().toLowerCase().replace(/[^a-z0-9]+/g,' ').trim().replace(/\s+/g,' '); }
function normKey(s){ return normTitle(s).replace(/ /g,''); }
function normSite(u){ let s=(u||'').toString().toLowerCase().trim(); s=s.replace(/^https?:\/\//,''); s=s.replace(/^www\./,''); s=s.split('/')[0]; s=s.replace(/[^a-z0-9.]+/g,''); return s; }

const companies = $('03 - Filter Valid Companies').all();
const rawContacts = $('04 - Get Contacts - Data2').all();
const existingEmails = $('E1 - Existing Emails').all();
const existingAnalyses = $('E2 - Existing Analyses').all();

const emailTitleSet = new Set();
const emailKeySet = new Set();
for (const r of existingEmails){ 
  const f = (r.json && r.json.fields) ? r.json.fields : (r.json||{}); 
  if(f && f.Company) emailTitleSet.add(normTitle(f.Company)); 
  if(f && f['Company Key']) emailKeySet.add(String(f['Company Key']).toLowerCase()); 
}

const analysisTitleSet = new Set();
const analysisKeySet = new Set();
for (const r of existingAnalyses){ 
  const f = (r.json && r.json.fields) ? r.json.fields : (r.json||{}); 
  if(f && f.Company) analysisTitleSet.add(normTitle(f.Company)); 
  if(f && f['Company Key']) analysisKeySet.add(String(f['Company Key']).toLowerCase()); 
}

const contactsByTitle = {};
const sentCompaniesSet = new Set();

for (const c of rawContacts){
  const f = (c.json && c.json.fields) ? c.json.fields : (c.json||{});
  if(!f || Object.keys(f).length===0) continue;

  const email = (f.email||'').toString().trim();
  const isVerified = f.emailVerification === true || String(f.emailVerification).toLowerCase() === 'true';
  const readyRaw = f['ready to send the message'];
  const isReadyToSend = readyRaw === true || String(readyRaw).toLowerCase() === 'true';

  const messageSentRaw = f['message sent'] != null ? f['message sent'] : f.sent;
  const isMessageSent = messageSentRaw === true || String(messageSentRaw).toLowerCase() === 'true';

  // FIX 1: Match on Company Name rather than Contact Job Title
  const companyName = f.company || f.companyName || f['Company Name'] || f.title || '';
  const key = normTitle(companyName);
  if(!key) continue;

  // Track if this company already had ANY message sent
  if(isMessageSent) {
    sentCompaniesSet.add(key);
    continue; 
  }

  if(!email || !isVerified || !isReadyToSend) continue;

  if(!contactsByTitle[key]) contactsByTitle[key] = [];

  const full = f.fullName || ((f.firstName||'') + ' ' + (f.lastName||'')).trim();

  contactsByTitle[key].push({ 
    firstName: f.firstName || '', 
    lastName: f.lastName || '', 
    fullName: full, 
    email: email,
    isVerified: isVerified,
    isReadyToSend: isReadyToSend,
    messageSent: isMessageSent
  });
}

const seen = {};
const out = [];

for (const comp of companies){
  const f = (comp.json && comp.json.fields) ? comp.json.fields : (comp.json||{});
  const title = f.title || '';
  const website = f.website || '';
  const tkey = normTitle(title);
  const ckey = normKey(title) + '|' + normSite(website);
  const providedKey = f['Company Key'] ? String(f['Company Key']).toLowerCase() : '';

  if(seen[ckey]) continue;
  seen[ckey] = true;

  const list = contactsByTitle[tkey] || [];
  const isAlreadySent = sentCompaniesSet.has(tkey);

  const emailList = list.map(function(p){ return p.email; }).filter(Boolean);
  const recipientEmails = emailList.join(', ');
  const recipientsText = list.map(function(p){ return (p.fullName||'').trim() + ' <' + p.email + '>'; }).join('\n');
  const status = (f['Analysis Status']||'').toString();

  const emailExists = emailTitleSet.has(tkey) || (providedKey && emailKeySet.has(providedKey)) || emailKeySet.has(ckey);
  const analysisExists = analysisTitleSet.has(tkey) || (providedKey && analysisKeySet.has(providedKey)) || analysisKeySet.has(ckey);
  const statusDone = status === 'Email Generated';

  let route = 'full';
  let skipReason = '';

  // ROUTING LOGIC
  if(isAlreadySent){
    route = 'no_contacts';
    skipReason = 'Already sent (message sent field is true)';
  } else if(list.length === 0){ 
    route = 'no_contacts'; 
    skipReason = 'No verified contacts found'; 
  } else if(emailExists){ 
    route = 'skip'; 
    skipReason = 'Email already exists'; 
  } else if(statusDone){ 
    route = 'skip'; 
    skipReason = 'Status Email Generated'; 
  } else if(analysisExists){ 
    route = 'skip'; 
    skipReason = 'Analysis already exists'; 
  }

  const safeTitle = title.replace(/"/g,'');
  const emailLookupFormula = 'LOWER({Company}) = "' + safeTitle.toLowerCase() + '"';

  out.push({ json: {
    recordId: comp.json.id,
    company: title,
    companyKey: ckey,
    normTitle: tkey,
    website: website,
    category: f.categoryName || f['categories/0'] || '',
    city: f.city || '',
    state: f.state || '',
    rating: f.totalScore != null ? f.totalScore : null,
    reviews: f.reviewsCount != null ? f.reviewsCount : null,
    url: f.url || '',
    contacts: list,
    recipientCount: list.length,
    recipientsText: recipientsText,
    recipientEmails: recipientEmails,
    recipientEmailArray: emailList,
    hasContacts: list.length > 0,
    route: route,
    skipReason: skipReason,
    emailLookupFormula: emailLookupFormula
  }});
}

return out;
